#include <iostream>
#include <string>
#include <vector>
using namespace std;

bool check(int k, int n, int m, const vector<int>& nextW) {
    int p = nextW[0];
    int cnt = 0;
    while (p < n) {
        cnt++;
        if (p + k < n) {
            p = nextW[p + k];
        } else {
            p = n;
        }
    }
    return cnt <= m;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    string s;
    cin >> n >> m >> s;

    // 如果初始序列全是 'R'，直接输出 0
    if (s.find('W') == string::npos) {
        cout << 0 << "\n";
        return 0;
    }

    // 预处理 nextW 数组
    vector<int> nextW(n, n);
    for (int i = n - 1; i >= 0; --i) {
        if (s[i] == 'W') {
            nextW[i] = i;
        } else if (i + 1 < n) {
            nextW[i] = nextW[i + 1];
        }
    }

    int l = 1, r = n;
    while (l < r) {
        int mid = (l + r) / 2;
        if (check(mid, n, m, nextW)) {
            r = mid;
        } else {
            l = mid + 1;
        }
    }
    cout << l << "\n";

    return 0;
}
